from collections import Counter

def canArrange(arr, k):
    if len(arr) % 2 != 0:
        return False
    count = Counter([x % k for x in arr])
    for rem in range(k):
        opp = (k - rem) % k
        if rem == 0 or (k % 2 == 0 and rem == k // 2):
            if count[rem] % 2 != 0:
                return False
        else:
            if count[rem] != count[opp]:
                return False
    return True
